239	
240			protected ProjectGenerationRequest createProjectGenerationRequest(OptionSet options) {
241				List<?> nonOptionArguments = new ArrayList<Object>(options.nonOptionArguments());
242				Assert.state(nonOptionArguments.size() <= 1, "Only the target location may be specified");
243				ProjectGenerationRequest request = new ProjectGenerationRequest();
244				request.setServiceUrl(options.valueOf(this.target));
245				applyConfiguredValue(options, this.bootVersion, request::setBootVersion);
246				applyConfiguredDependencies(options, request);
247				applyConfiguredValue(options, this.javaVersion, request::setJavaVersion);
248				applyConfiguredValue(options, this.packageName, request::setPackageName);
249				request.setBuild(options.valueOf(this.build));
250				request.setFormat(options.valueOf(this.format));
251				request.setDetectType(options.has(this.build) || options.has(this.format));
252				applyConfiguredValue(options, this.type, request::setType);
253				applyConfiguredValue(options, this.packaging, request::setPackaging);
254				applyConfiguredValue(options, this.language, request::setLanguage);
255				applyConfiguredValue(options, this.groupId, request::setGroupId);
256				applyConfiguredValue(options, this.artifactId, request::setArtifactId);
257				applyConfiguredValue(options, this.name, request::setName);
258				applyConfiguredValue(options, this.version, request::setVersion);
259				applyConfiguredValue(options, this.description, request::setDescription);
260				request.setExtract(options.has(this.extract));
261				if (nonOptionArguments.size() == 1) {
262					String output = (String) nonOptionArguments.get(0);
263					request.setOutput(output);
264				}
265				return request;
266			}
267	
268			private void applyConfiguredDependencies(OptionSet options, ProjectGenerationRequest request) {
269				if (!options.has(this.dependencies)) {
270					return;
271				}
272				for (String dependency : options.valueOf(this.dependencies).split(",")) {
273					request.getDependencies().add(dependency.trim());
274				}
275			}
276	
277			private void applyConfiguredValue(OptionSet options, OptionSpec<String> option, Consumer<String> setter) {
278				if (options.has(option)) {
279					setter.accept(options.valueOf(option));
280				}
281			}
282	
283			private static String processArgument(String argument) {
284				for (Map.Entry<String, String> entry : CAMEL_CASE_OPTIONS.entrySet()) {
285					String name = entry.getKey();
286					if (argument.startsWith(name + " ") || argument.startsWith(name + "=")) {
287						return entry.getValue() + argument.substring(name.length());
288					}
289				}
290				return argument;
291			}
